const raw = $input.first().json.config;

if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
  throw new Error('Client config must be a JSON object');
}

const failures = [];
const isObject = (value) => Boolean(value) && typeof value === 'object' && !Array.isArray(value);
const isText = (value) => typeof value === 'string' && value.trim().length > 0;
const fail = (message) => failures.push(message);
const requireObject = (value, path) => {
  if (!isObject(value)) {
    fail(`${path} must be an object`);
    return {};
  }
  return value;
};
const requireText = (object, key, path) => {
  if (!isText(object[key])) fail(`${path} must be a non-empty string`);
};
const requireSheets = (value, path) => {
  const sheets = requireObject(value, path);
  requireText(sheets, 'spreadsheetId', `${path}.spreadsheetId`);
  requireText(sheets, 'sheetName', `${path}.sheetName`);
  const columns = requireObject(sheets.columns, `${path}.columns`);
  if (!isText(columns.name)) fail(`${path}.columns.name must be a non-empty string`);
  if (!isText(columns.email) && !isText(columns.phone)) {
    fail(`${path}.columns must include email or phone`);
  }
  return sheets;
};

const legacy = !raw.version || Number(raw.version) < 2;
let config;

if (legacy) {
  const oldSheets = requireObject(raw.googleSheets, 'googleSheets');
  config = {
    version: 2,
    clientName: raw.clientName || 'Client',
    source: {
      type: 'webhook',
      defaultSource: (raw.defaults && raw.defaults.source) || 'unknown',
      allowedSources: [],
    },
    mapping: raw.mapping,
    crm: {
      provider: 'google_sheets',
      googleSheets: {
        spreadsheetId: oldSheets.spreadsheetId,
        leadsSheetName: oldSheets.leadsSheetName,
        columns: oldSheets.columns,
      },
    },
    journal: { enabled: false },
    notifications: {
      enabled: true,
      channels: ['telegram'],
      telegram: raw.telegram,
    },
    errors: {
      enabled: true,
      provider: 'google_sheets',
      googleSheets: {
        spreadsheetId: oldSheets.spreadsheetId,
        sheetName: oldSheets.errorsSheetName,
        columns: oldSheets.errorColumns,
      },
    },
  };
} else {
  config = JSON.parse(JSON.stringify(raw));
}

config.clientName = config.clientName || 'Client';
const source = requireObject(config.source, 'source');
if (source.type !== 'webhook') fail('source.type must be "webhook"');
if (!isText(source.defaultSource)) fail('source.defaultSource must be a non-empty string');
if (source.allowedSources !== undefined && !Array.isArray(source.allowedSources)) {
  fail('source.allowedSources must be an array');
}
if (Array.isArray(source.allowedSources)) {
  for (const item of source.allowedSources) {
    if (!isText(item)) fail('source.allowedSources must contain only non-empty strings');
  }
}

const mapping = requireObject(config.mapping, 'mapping');
for (const field of ['name', 'email', 'phone', 'source', 'message', 'externalId']) {
  requireText(mapping, field, `mapping.${field}`);
}

const crm = requireObject(config.crm, 'crm');
if (!['hubspot', 'google_sheets', 'none'].includes(crm.provider)) {
  fail('crm.provider must be one of: hubspot, google_sheets, none');
}

const leadFields = new Set(['name', 'firstName', 'lastName', 'email', 'phone', 'source', 'message', 'externalId']);

if (crm.provider === 'hubspot') {
  const hubspot = requireObject(crm.hubspot, 'crm.hubspot');
  if (!isText(hubspot.baseUrl)) {
    fail('crm.hubspot.baseUrl must be a non-empty string');
  } else if (!/^https?:\/\/[^\s/]+/i.test(hubspot.baseUrl)) {
    fail('crm.hubspot.baseUrl must be a valid http(s) URL');
  }
  if ((hubspot.phoneOnlyPolicy || 'skip') !== 'skip') {
    fail('crm.hubspot.phoneOnlyPolicy currently supports only "skip"');
  }
  if (hubspot.searchEmailProperty !== undefined && !isText(hubspot.searchEmailProperty)) {
    fail('crm.hubspot.searchEmailProperty must be a non-empty string');
  }
  const searchLimit = Number(hubspot.searchLimit || 10);
  if (!Number.isInteger(searchLimit) || searchLimit < 1 || searchLimit > 100) {
    fail('crm.hubspot.searchLimit must be an integer between 1 and 100');
  }
  if (hubspot.propertiesToReturn !== undefined) {
    if (!Array.isArray(hubspot.propertiesToReturn) || hubspot.propertiesToReturn.some((item) => !isText(item))) {
      fail('crm.hubspot.propertiesToReturn must be an array of non-empty strings');
    }
  }
  const propertyMapping = requireObject(hubspot.propertyMapping, 'crm.hubspot.propertyMapping');
  const entries = Object.entries(propertyMapping);
  if (entries.length === 0) fail('crm.hubspot.propertyMapping must contain at least one property');
  for (const [destination, sourceField] of entries) {
    if (!isText(destination)) fail('crm.hubspot.propertyMapping contains an empty destination property');
    if (!isText(sourceField) || !leadFields.has(sourceField)) {
      fail(`crm.hubspot.propertyMapping.${destination} must reference a valid Lead field`);
    }
  }
  if (!isText(propertyMapping.email)) {
    fail('crm.hubspot.propertyMapping.email is required for contact deduplication');
  }
}

if (crm.provider === 'google_sheets') {
  const sheets = requireObject(crm.googleSheets, 'crm.googleSheets');
  requireText(sheets, 'spreadsheetId', 'crm.googleSheets.spreadsheetId');
  requireText(sheets, 'leadsSheetName', 'crm.googleSheets.leadsSheetName');
  const columns = requireObject(sheets.columns, 'crm.googleSheets.columns');
  if (!isText(columns.name)) fail('crm.googleSheets.columns.name must be a non-empty string');
  if (!isText(columns.email) && !isText(columns.phone)) {
    fail('crm.googleSheets.columns must include email or phone');
  }
}

const journal = config.journal === undefined ? { enabled: false } : requireObject(config.journal, 'journal');
journal.enabled = Boolean(journal.enabled);
if (journal.enabled) {
  if (journal.provider !== 'google_sheets') fail('journal.provider must be "google_sheets"');
  const journalSheets = requireSheets(journal.googleSheets, 'journal.googleSheets');
  if (crm.provider === 'google_sheets') {
    const crmSheets = crm.googleSheets || {};
    if (crmSheets.spreadsheetId === journalSheets.spreadsheetId && crmSheets.leadsSheetName === journalSheets.sheetName) {
      fail('journal must target a different sheet than crm.googleSheets when CRM is Google Sheets');
    }
  }
}

const notifications = config.notifications === undefined ? { enabled: false } : requireObject(config.notifications, 'notifications');
notifications.enabled = Boolean(notifications.enabled);
if (notifications.enabled) {
  if (!Array.isArray(notifications.channels) || notifications.channels.length === 0) {
    fail('notifications.channels must contain at least one channel when notifications are enabled');
  }
  for (const channel of notifications.channels || []) {
    if (channel !== 'telegram') fail(`unsupported notification channel: ${channel}`);
  }
  if ((notifications.channels || []).includes('telegram')) {
    const telegram = requireObject(notifications.telegram, 'notifications.telegram');
    requireText(telegram, 'chatId', 'notifications.telegram.chatId');
    if (!isText(telegram.messageTemplate)) {
      fail('notifications.telegram.messageTemplate must be a non-empty string');
    } else {
      const allowed = new Set(['name', 'firstName', 'lastName', 'email', 'phone', 'source', 'message', 'externalId', 'requestId', 'crmStatus', 'crmProvider', 'crmContactId']);
      const placeholders = [...telegram.messageTemplate.matchAll(/\{\{\s*(\w+)\s*\}\}/g)].map((match) => match[1]);
      for (const placeholder of placeholders) {
        if (!allowed.has(placeholder)) fail(`notifications.telegram.messageTemplate contains unknown placeholder {{${placeholder}}}`);
      }
    }
  }
}

const errors = config.errors === undefined ? { enabled: false } : requireObject(config.errors, 'errors');
errors.enabled = Boolean(errors.enabled);
if (errors.enabled) {
  if (errors.provider !== 'google_sheets') fail('errors.provider must be "google_sheets"');
  const errorSheets = requireObject(errors.googleSheets, 'errors.googleSheets');
  requireText(errorSheets, 'spreadsheetId', 'errors.googleSheets.spreadsheetId');
  requireText(errorSheets, 'sheetName', 'errors.googleSheets.sheetName');
  const errorColumns = requireObject(errorSheets.columns, 'errors.googleSheets.columns');
  for (const field of ['createdAt', 'requestId', 'stage', 'error']) {
    if (!isText(errorColumns[field])) fail(`errors.googleSheets.columns.${field} must be a non-empty string`);
  }
}

if (crm.provider === 'none' && !journal.enabled) {
  fail('at least one persistence target is required: crm.provider or journal.enabled');
}

config.version = 2;
config.source = source;
config.source.allowedSources = Array.isArray(source.allowedSources) ? source.allowedSources : [];
config.crm = crm;
config.journal = journal;
config.notifications = notifications;
config.errors = errors;

if (config.crm.provider === 'hubspot') {
  const hubspot = config.crm.hubspot;
  hubspot.baseUrl = hubspot.baseUrl.replace(/\/+$/, '');
  hubspot.phoneOnlyPolicy = 'skip';
  hubspot.searchEmailProperty = hubspot.searchEmailProperty || 'email';
  delete hubspot.searchPhoneProperty;
  hubspot.searchLimit = Number(hubspot.searchLimit || 10);
  hubspot.propertiesToReturn = Array.isArray(hubspot.propertiesToReturn)
    ? hubspot.propertiesToReturn
    : ['email', 'phone', 'firstname', 'lastname'];
}

if (failures.length > 0) {
  throw new Error(`Invalid client config: ${failures.join('; ')}`);
}

return [{ json: { config } }];

const config = $('Validate Client Config').first().json.config;
const rawBody = $('Lead Webhook').first().json.body;
const bodyIsObject = rawBody !== null && typeof rawBody === 'object' && !Array.isArray(rawBody);
const payload = bodyIsObject ? rawBody : {};

const mapping = config.mapping;
const getByPath = (obj, path) => {
  if (typeof path !== 'string' || path.length === 0) return undefined;
  return path.split('.').reduce((acc, key) => (acc === null || acc === undefined ? undefined : acc[key]), obj);
};
const asText = (value) => {
  if (value === null || value === undefined) return null;
  if (typeof value === 'string') {
    const trimmed = value.trim();
    return trimmed.length > 0 ? trimmed : null;
  }
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  return null;
};

const name = asText(getByPath(payload, mapping.name));
const emailRaw = asText(getByPath(payload, mapping.email));
const phoneRaw = asText(getByPath(payload, mapping.phone));
const sourceRaw = asText(getByPath(payload, mapping.source));
const phoneDigits = phoneRaw ? phoneRaw.replace(/\D/g, '') : '';
const phone = phoneDigits.length > 0
  ? (phoneRaw.trim().startsWith('+') ? '+' : '') + phoneDigits
  : null;
const nameParts = name ? name.split(/\s+/) : [];
const firstName = nameParts.length > 0 ? nameParts[0] : null;
const lastName = nameParts.length > 1 ? nameParts.slice(1).join(' ') : null;

const allowedSources = Array.isArray(config.source.allowedSources)
  ? config.source.allowedSources.map((item) => item.toLowerCase())
  : [];
const sourceValue = sourceRaw ? sourceRaw.toLowerCase() : null;
const source = sourceValue && (allowedSources.length === 0 || allowedSources.includes(sourceValue))
  ? sourceValue
  : (config.source.defaultSource || 'unknown').toLowerCase();
const sourceAdjusted = Boolean(sourceRaw && sourceValue !== source);
const requestId = $execution && $execution.id ? String($execution.id) : null;
const receivedAt = new Date().toISOString();

return [{
  json: {
    lead: {
      name,
      firstName,
      lastName,
      email: emailRaw ? emailRaw.toLowerCase() : null,
      phone,
      source,
      message: asText(getByPath(payload, mapping.message)),
      externalId: asText(getByPath(payload, mapping.externalId)),
    },
    meta: { requestId, receivedAt, bodyIsObject, sourceAdjusted },
    config,
  },
}];

const { lead, meta, config } = $input.first().json;
const errors = [];

if (!meta.bodyIsObject) errors.push('Request body must be a JSON object.');
if (!lead.name) errors.push('name is required.');
if (!lead.email && !lead.phone) errors.push('At least one of email or phone is required.');

return [{
  json: {
    lead,
    meta,
    config,
    validation: { valid: errors.length === 0, errors },
  },
}];

const validated = $('Validate Lead').first().json;
const config = $('Validate Client Config').first().json.config;
const crm = {
  provider: 'none',
  status: 'skipped',
  contactId: null,
  matchedBy: null,
  matchCount: 0,
  reason: 'crm_disabled',
  httpStatus: 202,
};
return [{
  json: {
    lead: validated.lead,
    meta: validated.meta,
    config,
    crm,
    journal: null,
    notifications: null,
    warnings: [],
    hasWarning: false,
  },
}];

const validated = $('Validate Lead').first().json;
const config = $('Validate Client Config').first().json.config;
const columns = config.crm.googleSheets.columns;
const values = {
  createdAt: validated.meta.receivedAt,
  externalId: validated.lead.externalId,
  name: validated.lead.name,
  firstName: validated.lead.firstName,
  lastName: validated.lead.lastName,
  email: validated.lead.email,
  phone: validated.lead.phone,
  source: validated.lead.source,
  message: validated.lead.message,
  requestId: validated.meta.requestId,
};
const row = {};
for (const [key, header] of Object.entries(columns)) {
  if (typeof header !== 'string' || header.length === 0) continue;
  row[header] = values[key] === null || values[key] === undefined ? '' : values[key];
}
if (Object.keys(row).length === 0) throw new Error('No Google Sheets CRM columns are configured');
return [{ json: row }];

const validated = $('Validate Lead').first().json;
const config = $('Validate Client Config').first().json.config;
const crm = {
  provider: 'google_sheets',
  status: 'created',
  contactId: null,
  matchedBy: null,
  matchCount: 0,
  reason: null,
  httpStatus: 201,
};
return [{
  json: {
    lead: validated.lead,
    meta: validated.meta,
    config,
    crm,
    journal: null,
    notifications: null,
    warnings: [],
    hasWarning: false,
  },
}];

const validated = $('Validate Lead').first().json;
const config = $('Validate Client Config').first().json.config;
const hubspot = config.crm.hubspot;
const lead = validated.lead;

const contactProperties = {};
for (const [destination, sourceField] of Object.entries(hubspot.propertyMapping)) {
  const value = lead[sourceField];
  if (value !== null && value !== undefined && String(value).trim() !== '') {
    contactProperties[destination] = String(value);
  }
}

let action = 'search';
let reason = null;
let matchedBy = 'email';
let searchProperty = hubspot.searchEmailProperty;
let searchValue = lead.email;

if (!lead.email) {
  action = 'skip';
  reason = 'phone_only';
  matchedBy = null;
  searchValue = null;
}

const requestBody = action === 'search'
  ? {
      filterGroups: [{ filters: [{ propertyName: searchProperty, operator: 'EQ', value: searchValue }] }],
      properties: hubspot.propertiesToReturn,
      limit: hubspot.searchLimit,
    }
  : null;

return [{
  json: {
    lead,
    meta: validated.meta,
    config,
    action,
    reason,
    matchedBy,
    searchProperty,
    searchValue,
    contactProperties,
    requestBody,
  },
}];

const response = $input.first().json;
const prepared = $('Prepare HubSpot Contact').first().json;
const results = Array.isArray(response)
  ? response
  : (Array.isArray(response.results) ? response.results : []);
const matchCount = results.length;

let action = 'create';
let reason = null;
let contactId = null;

if (matchCount === 1) {
  action = 'update';
  contactId = String(results[0].id ?? results[0].vid ?? '');
} else if (matchCount > 1) {
  action = 'skip';
  reason = 'ambiguous_match';
}

return [{
  json: {
    ...prepared,
    action,
    reason,
    contactId,
    matchCount,
    requestBody: { properties: prepared.contactProperties },
    searchResult: results[0] || null,
  },
}];

const response = $input.first().json;
const prepared = $('Resolve HubSpot Match').first().json;
const status = prepared.action === 'update' ? 'updated' : 'created';
const contactId = String(response.id ?? response.vid ?? prepared.contactId ?? '');
const crm = {
  provider: 'hubspot',
  status,
  contactId,
  matchedBy: prepared.matchedBy,
  matchCount: prepared.matchCount,
  reason: null,
  httpStatus: status === 'created' ? 201 : 200,
};
return [{
  json: {
    lead: prepared.lead,
    meta: prepared.meta,
    config: prepared.config,
    crm,
    journal: null,
    notifications: null,
    warnings: [],
    hasWarning: false,
  },
}];

const data = $input.first().json;
const reason = data.reason || (data.matchCount > 1 ? 'ambiguous_match' : 'skipped');
const crm = {
  provider: 'hubspot',
  status: 'skipped',
  contactId: data.contactId || null,
  matchedBy: data.matchedBy || null,
  matchCount: data.matchCount || 0,
  reason,
  httpStatus: 202,
};
return [{
  json: {
    lead: data.lead,
    meta: data.meta,
    config: data.config,
    crm,
    journal: null,
    notifications: null,
    warnings: [],
    hasWarning: false,
  },
}];

const input = $input.first().json;
const config = $('Validate Client Config').first().json.config;
const validated = $('Validate Lead').first().json;
const rawError = input.error;
const detail = typeof rawError === 'string'
  ? rawError
  : (rawError && (rawError.message || rawError.description)) || input.message || 'CRM request failed';
const rateLimited = /(^|\D)429(\D|$)|rate limit|too many requests|spacing your requests|batching settings/i.test(String(detail));
const provider = config.crm.provider;
const crm = {
  provider,
  status: 'failed',
  contactId: null,
  matchedBy: null,
  matchCount: 0,
  reason: rateLimited ? 'rate_limited' : 'api_error',
  httpStatus: rateLimited ? 429 : 502,
  error: String(detail).slice(0, 2000),
};
const response = {
  ok: false,
  error: rateLimited ? 'crm_rate_limited' : 'crm_write_failed',
  message: rateLimited ? 'CRM rate limit reached. Retry later.' : 'Lead was not saved to the CRM.',
  saved: false,
  notified: false,
  requestId: validated.meta.requestId,
  externalId: validated.lead.externalId,
  crm: { provider, status: 'failed', reason: crm.reason },
};
return [{
  json: {
    lead: validated.lead,
    meta: validated.meta,
    config,
    crm,
    response,
    httpStatus: crm.httpStatus,
    hasWarning: false,
  },
}];

const context = $('Build CRM Failure').first().json;
const config = context.config;
const columns = config.errors.googleSheets.columns;
const values = {
  createdAt: new Date().toISOString(),
  requestId: context.meta.requestId,
  stage: `crm_${context.crm.provider}`,
  error: context.crm.error || 'CRM request failed',
  leadJson: JSON.stringify(context.lead).slice(0, 4000),
  executionId: $execution && $execution.id ? String($execution.id) : '',
};
const row = {};
for (const [key, header] of Object.entries(columns)) {
  if (typeof header !== 'string' || header.length === 0) continue;
  if (values[key] !== undefined && values[key] !== null) row[header] = values[key];
}
if (Object.keys(row).length === 0) throw new Error('No Google Sheets error columns are configured');
return [{ json: row }];

const context = $input.first().json;
const config = context.config;
const columns = config.journal.googleSheets.columns;
const values = {
  createdAt: context.meta.receivedAt,
  externalId: context.lead.externalId,
  name: context.lead.name,
  firstName: context.lead.firstName,
  lastName: context.lead.lastName,
  email: context.lead.email,
  phone: context.lead.phone,
  source: context.lead.source,
  message: context.lead.message,
  requestId: context.meta.requestId,
  crmProvider: context.crm.provider,
  crmStatus: context.crm.status,
  crmContactId: context.crm.contactId,
};
const row = {};
for (const [key, header] of Object.entries(columns)) {
  if (typeof header !== 'string' || header.length === 0) continue;
  row[header] = values[key] === null || values[key] === undefined ? '' : values[key];
}
if (Object.keys(row).length === 0) throw new Error('No Google Sheets journal columns are configured');
return [{ json: row }];

const context = $('Build Journal Context').first().json;
return [{
  json: {
    ...context,
    journal: { enabled: true, status: 'saved' },
    hasWarning: Boolean(context.hasWarning),
  },
}];

const context = $('Build Journal Context').first().json;
const input = $input.first().json;
const rawError = input.error;
const detail = typeof rawError === 'string'
  ? rawError
  : (rawError && (rawError.message || rawError.description)) || input.message || 'Google Sheets journal write failed';
return [{
  json: {
    ...context,
    journal: { enabled: true, status: 'failed', error: String(detail).slice(0, 1000) },
    warnings: [...(context.warnings || []), 'journal_write_failed'],
    hasWarning: true,
  },
}];

const context = $input.first().json;
return [{
  json: {
    ...context,
    journal: { enabled: false, status: 'disabled' },
    hasWarning: Boolean(context.hasWarning),
  },
}];

const context = $input.first().json;
const config = context.config;
const telegram = config.notifications.telegram;
const escapeHtml = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');
const values = {
  name: escapeHtml(context.lead.name || '-'),
  firstName: escapeHtml(context.lead.firstName || '-'),
  lastName: escapeHtml(context.lead.lastName || '-'),
  email: escapeHtml(context.lead.email || '-'),
  phone: escapeHtml(context.lead.phone || '-'),
  source: escapeHtml(context.lead.source || '-'),
  message: escapeHtml(context.lead.message || '-'),
  externalId: escapeHtml(context.lead.externalId || '-'),
  requestId: escapeHtml(context.meta.requestId || '-'),
  crmStatus: escapeHtml(context.crm.status || '-'),
  crmProvider: escapeHtml(context.crm.provider || '-'),
  crmContactId: escapeHtml(context.crm.contactId || '-'),
};
let text = String(telegram.messageTemplate);
for (const [key, value] of Object.entries(values)) {
  const pattern = new RegExp(`\\{\\{\\s*${key}\\s*\\}\\}`, 'g');
  text = text.replace(pattern, () => value);
}
if (text.length > 4000) {
  text = `${text.slice(0, 3980).replace(/&[a-zA-Z#0-9]*$/, '')}\n[truncated]`;
}
return [{ json: { ...context, text } }];

const context = $('Build Journal Context').first().json;
const input = $input.first().json;
const rawError = input.error;
const detail = typeof rawError === 'string'
  ? rawError
  : (rawError && (rawError.message || rawError.description)) || input.message || 'Notification message build failed';
return [{
  json: {
    ...context,
    notifications: {
      enabled: true,
      status: 'failed',
      channels: context.config.notifications.channels,
      error: String(detail).slice(0, 1000),
    },
    warnings: [...(context.warnings || []), 'notification_send_failed'],
    hasWarning: true,
  },
}];

const context = $('Build Notification Message').first().json;
return [{
  json: {
    ...context,
    notifications: {
      enabled: true,
      status: 'sent',
      channels: context.config.notifications.channels,
    },
    hasWarning: Boolean(context.hasWarning),
  },
}];

const context = $('Build Notification Message').first().json;
const input = $input.first().json;
const rawError = input.error;
const detail = typeof rawError === 'string'
  ? rawError
  : (rawError && (rawError.message || rawError.description)) || input.message || 'Telegram send failed';
return [{
  json: {
    ...context,
    notifications: {
      enabled: true,
      status: 'failed',
      channels: context.config.notifications.channels,
      error: String(detail).slice(0, 1000),
    },
    warnings: [...(context.warnings || []), 'notification_send_failed'],
    hasWarning: true,
  },
}];

const context = $input.first().json;
return [{
  json: {
    ...context,
    notifications: { enabled: false, status: 'disabled', channels: [] },
    hasWarning: Boolean(context.hasWarning),
  },
}];

const context = $input.first().json;
const { lead, meta, crm, config } = context;
const journal = context.journal || { enabled: false, status: 'disabled' };
const notifications = context.notifications || { enabled: false, status: 'disabled', channels: [] };
const warnings = Array.isArray(context.warnings) ? [...context.warnings] : [];
const saved = ['created', 'updated'].includes(crm.status) || journal.status === 'saved';
const notified = notifications.status === 'sent';
let status = crm.status;
if (crm.status === 'skipped') status = 'crm_skipped';
if (notifications.status === 'failed') {
  if (crm.status === 'created') status = 'saved_with_notification_error';
  else if (crm.status === 'updated') status = 'updated_with_notification_error';
  else if (crm.status === 'skipped') status = 'crm_skipped_with_notification_error';
}
const httpStatus = crm.httpStatus || (crm.status === 'updated' ? 200 : crm.status === 'skipped' ? 202 : 201);
const response = {
  ok: crm.status !== 'failed',
  status,
  requestId: meta.requestId,
  externalId: lead.externalId,
  saved,
  notified,
  crm: {
    provider: crm.provider,
    status: crm.status,
    contactId: crm.contactId || null,
    matchedBy: crm.matchedBy || null,
    matchCount: crm.matchCount || 0,
    reason: crm.reason || null,
  },
  journal: { enabled: journal.enabled, status: journal.status },
  notifications: {
    enabled: notifications.enabled,
    status: notifications.status,
    channels: notifications.channels || [],
  },
  warnings,
};
return [{ json: { response, httpStatus, hasWarning: Boolean(context.hasWarning) } }];

const input = $input.first().json;
const rawError = input.error;
const detail = typeof rawError === 'string'
  ? rawError
  : (rawError && (rawError.message || rawError.description)) || input.message || 'Configuration error';
const requestId = $execution && $execution.id ? String($execution.id) : null;
return [{
  json: {
    response: {
      ok: false,
      error: 'configuration_error',
      message: 'Lead intake is not configured correctly or the request could not be normalized.',
      detail: String(detail).slice(0, 800),
      requestId,
    },
  },
}];
